<div><div className="integration-symbol"><Sparkles size={18}/></div><div><b>AI analyst</b><p>{aiProviderStatus==='Not configured'?'No AI connection has been set up for this workspace.':aiProviderStatus==='Unable to check configuration'?'The API health check failed, so search-service setup could not be determined.':aiProviderStatus==='Checking configuration'?'Checking server-side search-service setup…':aiProviderStatus.includes('successful review')?aiProviderStatus+' in a saved investigation. Output still needs human source verification.':aiProviderStatus+'. A successful review must still be tested in an investigation.'}</p></div><span className="provider-pending">{aiProviderStatus==='Not configured'?'NOT CONFIGURED':aiProviderStatus==='Checking configuration'?'CHECKING':aiProviderStatus==='Unable to check configuration'?'UNKNOWN':aiProviderStatus.includes('successful review')?'END-TO-END TEST PASSED':'CONFIGURED · UNVERIFIED'}</span></div>
